# owner: platform
import unittest

from tests.support import data_file
from rosterkit.reader import read_roster
from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows

def make(last, first, section, email):
    return Student("1", last, first, section, email)

def sefa(email):
    return make("Quillon", "Sefa", "A", email)

class ContactRowTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows(
            [
                make("Varrow", "Ines", "A", "i@x.edu"),
                make("Thistle", "Bram", "B", "b@x.edu")
            ]
        )
        self.assertEqual(
            rows,
            [
                "Thistle, Bram  B  b@x.edu",
                "Varrow, Ines   A  i@x.edu"
            ]
        )

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as ctx:
            contact_rows([sefa(None)])
        self.assertIn("Quillon, Sefa", str(ctx.exception))

    def test_blank_email_counts_as_missing(self):
        with self.assertRaises(ProjectError):
            contact_rows([sefa("  ")])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])

    def test_roster_file_without_email_fails(self):
        students = read_roster(data_file("roster.csv"))
        with self.assertRaises(ProjectError) as ctx:
            contact_rows(students)
        self.assertIn("Quillon", str(ctx.exception))
